import{_ as a,o as n,c as e,a5 as t}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"14. Control Flow: if, else, switch","description":"The Little Book of C — 14. Control Flow: if, else, switch","frontmatter":{"title":"14. Control Flow: if, else, switch","date":"2026-07-04","categories":"[C 教程]","tags":"[C, Little Book of C, Language Basics]","description":"The Little Book of C — 14. Control Flow: if, else, switch","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":"14","sidebarWeight":"14","lang":"en-US","alternateEn":"/posts/c教程/en-US/02-Language Basics/014-Control Flow if, else, switch","alternateZh":"/posts/c教程/zh-CN/02-语言基础/014-Control Flow if, else, switch"},"headers":[],"relativePath":"posts/c教程/en-US/02-Language Basics/014-Control Flow if, else, switch.md","filePath":"posts/c教程/en-US/02-Language Basics/014-Control Flow if, else, switch.md","lastUpdated":1790163617000}'),p={name:"posts/c教程/en-US/02-Language Basics/014-Control Flow if, else, switch.md"};function i(o,s,l,c,r,d){return n(),e("div",null,[...s[0]||(s[0]=[t(`<p>[中文版本](/posts/c教程/zh-CN/02-语言基础/014-Control Flow if, else, switch)</p><p>Programs become powerful when they can decide, when they can choose one path or another depending on data or conditions. In C, control flow statements give you that power. They determine how your program moves through different parts of your code.</p><h4 id="tiny-code" tabindex="-1">Tiny Code <a class="header-anchor" href="#tiny-code" aria-label="Permalink to &quot;Tiny Code&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int temperature = 30;</span></span>
<span class="line"><span>    if (temperature &gt; 35) {</span></span>
<span class="line"><span>        printf(&quot;It&#39;s too hot!\\n&quot;);</span></span>
<span class="line"><span>    } else if (temperature &gt; 25) {</span></span>
<span class="line"><span>        printf(&quot;It&#39;s warm.\\n&quot;);</span></span>
<span class="line"><span>    } else {</span></span>
<span class="line"><span>        printf(&quot;It&#39;s cool.\\n&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>It&#39;s warm.</span></span></code></pre></div><p>This is how you express logic in C: by checking conditions and executing only the code that matches.</p><h4 id="the-if-and-else-structure" tabindex="-1">The if and else Structure <a class="header-anchor" href="#the-if-and-else-structure" aria-label="Permalink to &quot;The if and else Structure&quot;">​</a></h4><p>The basic pattern looks like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (condition) {</span></span>
<span class="line"><span>    // do something if true</span></span>
<span class="line"><span>} else if (another_condition) {</span></span>
<span class="line"><span>    // do something else</span></span>
<span class="line"><span>} else {</span></span>
<span class="line"><span>    // default action</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Each<code>if</code> or<code>else if</code> checks a condition that must evaluate to<code>true</code>(non-zero) or<code>false</code>(zero).</p><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int score = 85;</span></span>
<span class="line"><span>if (score &gt;= 90)</span></span>
<span class="line"><span>    printf(&quot;Grade: A\\n&quot;);</span></span>
<span class="line"><span>else if (score &gt;= 80)</span></span>
<span class="line"><span>    printf(&quot;Grade: B\\n&quot;);</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>    printf(&quot;Grade: C or below\\n&quot;);</span></span></code></pre></div><h4 id="comparison-and-boolean-logic" tabindex="-1">Comparison and Boolean Logic <a class="header-anchor" href="#comparison-and-boolean-logic" aria-label="Permalink to &quot;Comparison and Boolean Logic&quot;">​</a></h4><p>C doesn’t have a built-in<code>bool</code> type in older standards, but since C99, you can include it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdbool.h&gt;</span></span>
<span class="line"><span>bool is_ready = true;</span></span>
<span class="line"><span>if (is_ready) printf(&quot;Let&#39;s go!\\n&quot;);</span></span></code></pre></div><p>Behind the scenes,<code>true</code> is just<code>1</code> and<code>false</code> is<code>0</code>.</p><h4 id="nested-if-statements" tabindex="-1">Nested if Statements <a class="header-anchor" href="#nested-if-statements" aria-label="Permalink to &quot;Nested if Statements&quot;">​</a></h4><p>You can nest decisions for more complex logic:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (x &gt; 0) {</span></span>
<span class="line"><span>    if (x % 2 == 0)</span></span>
<span class="line"><span>        printf(&quot;Positive even number\\n&quot;);</span></span>
<span class="line"><span>    else</span></span>
<span class="line"><span>        printf(&quot;Positive odd number\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Just be careful, too much nesting makes code harder to read. When logic gets complex, consider reorganizing or using a<code>switch</code> statement.</p><h4 id="the-switch-statement" tabindex="-1">The switch Statement <a class="header-anchor" href="#the-switch-statement" aria-label="Permalink to &quot;The switch Statement&quot;">​</a></h4><p><code>switch</code> is a clean way to test one variable against several fixed values.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int day = 3;</span></span>
<span class="line"><span>    switch (day) {</span></span>
<span class="line"><span>        case 1:</span></span>
<span class="line"><span>            printf(&quot;Monday\\n&quot;);</span></span>
<span class="line"><span>            break;</span></span>
<span class="line"><span>        case 2:</span></span>
<span class="line"><span>            printf(&quot;Tuesday\\n&quot;);</span></span>
<span class="line"><span>            break;</span></span>
<span class="line"><span>        case 3:</span></span>
<span class="line"><span>            printf(&quot;Wednesday\\n&quot;);</span></span>
<span class="line"><span>            break;</span></span>
<span class="line"><span>        default:</span></span>
<span class="line"><span>            printf(&quot;Another day\\n&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Wednesday</span></span></code></pre></div><p>Each<code>case</code> label marks a potential branch.<code>break</code> stops the switch from “falling through” into the next case.</p><p>You can group multiple cases:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>switch (ch) {</span></span>
<span class="line"><span>    case &#39;a&#39;:</span></span>
<span class="line"><span>    case &#39;A&#39;:</span></span>
<span class="line"><span>        printf(&quot;Letter A detected\\n&quot;);</span></span>
<span class="line"><span>        break;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="the-ternary-operator" tabindex="-1">The Ternary Operator <a class="header-anchor" href="#the-ternary-operator" aria-label="Permalink to &quot;The Ternary Operator&quot;">​</a></h4><p>For quick decisions, you can use the conditional operator:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int age = 20;</span></span>
<span class="line"><span>printf(&quot;%s\\n&quot;, (age &gt;= 18) ? &quot;Adult&quot; : &quot;Minor&quot;);</span></span></code></pre></div><p>This is equivalent to:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>if (age &gt;= 18)</span></span>
<span class="line"><span>    printf(&quot;Adult\\n&quot;);</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>    printf(&quot;Minor\\n&quot;);</span></span></code></pre></div><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Control flow gives your programs intelligence. Instead of running straight through, your code reacts to input, conditions, and data. C’s branching statements are simple but flexible, they’re the building blocks of everything from sorting algorithms to operating system schedulers.</p><p>When you understand how to control execution, you can shape your program’s logic precisely.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><p>Write a program that:</p><ul><li>Reads an integer from the user.</li><li>Prints whether it’s positive, negative, or zero.</li></ul><p>Extend it:</p><ul><li>If it’s positive, print whether it’s even or odd.</li></ul><p>Use a<code>switch</code> statement:</p><ul><li>Ask for a number 1–7.</li><li>Print the day of the week that matches.</li></ul><p>Try replacing your<code>if</code> statements with a ternary operator where it makes sense.</p><p>Control flow is how you think in code, it’s how you teach your program to make decisions just like you do.</p>`,46)])])}const g=a(p,[["render",i]]);export{u as __pageData,g as default};
